function parseVec(s){
  if(!s || !String(s).trim()) return { value:null, error:'向量为空' };
  var parts=String(s).trim().split(/[,\s]+/).filter(function(x){return x.length;});
  var out=[];
  for(var i=0;i<parts.length;i++){
    var n=Number(parts[i]);
    if(!isFinite(n)) return { value:null, error:'非法数字: '+parts[i] };
    out.push(n);
  }
  return { value:out, error:null };
}
function dot(a,b){ var s=0; for(var i=0;i<a.length;i++) s+=a[i]*b[i]; return s; }
function norm(a){ return Math.sqrt(dot(a,a)); }
function cosineSim(a,b){
  if(a.length!==b.length) throw new Error('DIM_MISMATCH');
  var na=norm(a), nb=norm(b);
  if(na===0||nb===0) throw new Error('ZERO_VECTOR');
  return dot(a,b)/(na*nb);
}
function euclidean(a,b){
  if(a.length!==b.length) throw new Error('DIM_MISMATCH');
  var s=0; for(var i=0;i<a.length;i++){ var d=a[i]-b[i]; s+=d*d; }
  return Math.sqrt(s);
}
function manhattan(a,b){
  if(a.length!==b.length) throw new Error('DIM_MISMATCH');
  var s=0; for(var i=0;i<a.length;i++) s+=Math.abs(a[i]-b[i]);
  return s;
}
function topK(query, docs, k, metric){
  metric = metric || 'cosine';
  var scored = docs.map(function(d, idx){
    var s;
    if(metric==='cosine') s=cosineSim(query, d.vec);
    else if(metric==='dot') s=dot(query, d.vec);
    else if(metric==='manhattan') s=-manhattan(query, d.vec);
    else s=-euclidean(query, d.vec);
    return { id:(d.id!==undefined?d.id:idx), score:s };
  });
  scored.sort(function(x,y){ return y.score-x.score; });
  return scored.slice(0, k||scored.length);
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { parseVec:parseVec, dot:dot, norm:norm, cosineSim:cosineSim,
    euclidean:euclidean, manhattan:manhattan, topK:topK };
}
if (typeof window !== 'undefined') {
  window.VectorForgePure = { parseVec:parseVec, dot:dot, norm:norm, cosineSim:cosineSim,
    euclidean:euclidean, manhattan:manhattan, topK:topK };
}
